<section class="form-panel" id="practical"><h2>כתובת, מפה ופרטי ביקור</h2><p>המידע נשמר בנפרד מהמאמר והתרגומים שבעריכה. כל מתג קובע אם השדה יוצג; שדה ריק אינו מוצג. אין להזין שעות או מיקום שלא נבדקו.</p>
<form method="get"><label>בחרו פריט<select name="practical_id"><?php foreach($d->query('SELECT id,document FROM editorial_records ORDER BY id') as $row):$ed=json_decode($row['document'],true)['editorial'];?><option value="<?=e($row['id'])?>" <?=($_GET['practical_id']??'')===$row['id']?'selected':''?>><?=e($row['id'].' — '.($ed['translations']['he']['title']??'טיוטה'))?></option><?php endforeach?></select></label><button>פתיחת פרטי הפריט</button></form>
<?php if(!empty($_GET['practical_id'])):try{$pb=contentTransfer(['mode'=>'practical_export','ids'=>[(string)$_GET['practical_id']]]);$pr=$pb['records'][0];$p=$pr['data'];?>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="practical_save"><input type="hidden" name="id" value="<?=e($pr['id'])?>"><input type="hidden" name="revision" value="<?=$pr['revision']?>">
<?php foreach(['address'=>'כתובת','map'=>'מפה','official'=>'פרטי אתר רשמי','hours'=>'שעות פתיחה','directions'=>'איך מגיעים'] as $key=>$label):?><label><input type="checkbox" name="visible[<?=$key?>]" value="1" <?=!empty($p['visibility'][$key])?'checked':''?>> הצגת <?=e($label)?></label><?php endforeach?>
<?php foreach(['official_url'=>'כתובת האתר הרשמי','map_query'=>'שם המקום והעיר לחיפוש מפה','latitude'=>'קו רוחב מאומת (לא חובה)','longitude'=>'קו אורך מאומת (לא חובה)','checked_at'=>'תאריך בדיקה YYYY-MM-DD'] as $key=>$label):?><label><?=e($label)?><input name="<?=e($key)?>" value="<?=e($p[$key]??'')?>" dir="ltr"></label><?php endforeach?>
<?php foreach(contentTransfer(['mode'=>'locales'])['locales'] as $locale):?><fieldset dir="<?=e($locale['direction'])?>"><legend><?=e($locale['label'])?></legend><?php foreach(['address'=>'כתובת','hours'=>'שעות פתיחה','directions'=>'הוראות הגעה'] as $key=>$label):?><label><?=e($label)?><textarea name="translations[<?=e($locale['code'])?>][<?=$key?>]" rows="3"><?=e($p['translations'][$locale['code']][$key]??'')?></textarea></label><?php endforeach?></fieldset><?php endforeach?>
<button>שמירת פרטי הביקור וההצגה באתר</button></form><?php }catch(Throwable $err){?><p>לא ניתן לטעון את הפריט.</p><?php }endif?>
